const cfg = $('Config').first().json;
const j = $input.first().json;
const t0 = Date.now();

// Evento que envia Supabase cuando el supervisor valida o rechaza un reporte
if (j.body && j.body.record) {
  const hdr = j.headers || {};
  const rec = j.body.record;
  const old = j.body.old_record || {};
  const cambio = old.estado !== rec.estado && ['revisado', 'rechazado'].includes(rec.estado);
  if ((hdr['x-webhook-secret'] || '') !== cfg.webhook_secret || !cambio || !rec.telegram_chat_id) {
    return [{ json: { kind: 'ignorar' } }];
  }
  return [{ json: { kind: 'estado', t0, chat_id: rec.telegram_chat_id, report_id: rec.id, estado: rec.estado, comentario: rec.comentario_supervisor || '', equipo: rec.equipo || '' } }];
}

// Eventos de Telegram
const cb = j.callback_query;
const m = j.message;
const nombre = (u) => [u.first_name, u.last_name].filter(Boolean).join(' ');

if (cb) {
  return [{ json: { kind: 'callback', t0, chat_id: cb.message.chat.id, callback_id: cb.id, message_id: cb.message.message_id, data: cb.data || '', from_name: nombre(cb.from) } }];
}
if (!m) return [{ json: { kind: 'ignorar' } }];

const base = { t0, chat_id: m.chat.id, message_id: m.message_id, from_name: nombre(m.from), first_name: m.from.first_name || m.from.username || 'técnico', username: m.from.username || '' };
const replyTxt = (m.reply_to_message && (m.reply_to_message.text || m.reply_to_message.caption)) || '';
base.reply_id = (replyTxt.match(/ID:\s*([0-9a-fA-F-]{36})/) || [])[1] || '';

if (m.voice || m.audio) {
  const a = m.voice || m.audio;
  return [{ json: { ...base, kind: 'voice', file_id: a.file_id, duration: a.duration || 0 } }];
}
if (m.text) {
  if (m.text.startsWith('/')) return [{ json: { ...base, kind: 'command', command: m.text.split(/[\s@]/)[0].toLowerCase() } }];
  return [{ json: { ...base, kind: 'text', text: m.text } }];
}
return [{ json: { ...base, kind: 'command', command: '/no_soportado' } }];

const cfg = $('Config').first().json;
const ctx = $input.first().json;
if (['estado', 'ignorar'].includes(ctx.kind) || !cfg.require_whitelist) {
  return [{ json: { ...ctx, authorized: true } }];
}
try {
  const r = await this.helpers.httpRequest({
    method: 'GET',
    url: `${cfg.supabase_url}/rest/v1/usuarios_telegram?chat_id=eq.${ctx.chat_id}&activo=eq.true&select=chat_id,nombre`,
    headers: { apikey: cfg.supabase_key, Authorization: `Bearer ${cfg.supabase_key}` },
    json: true,
  });
  const ok = Array.isArray(r) && r.length > 0;
  return [{ json: { ...ctx, authorized: ok, tecnico_registrado: ok ? r[0].nombre : null } }];
} catch (e) {
  return [{ json: { ...ctx, authorized: false } }];
}

const esc = (t) => String(t === null || t === undefined ? '' : t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const c = $input.first().json;
let text;
if (c.command === '/no_soportado') {
  text = '⚠️ Solo puedo procesar <b>audios</b> y <b>mensajes de texto</b>.';
} else {
  const nombre = esc(c.tecnico_registrado || c.first_name || 'técnico');
  text = `👋 Hola, <b>${nombre}</b>. Soy <b>MaintAI</b>, tu asistente de reportes de mantenimiento.

Puedes enviarme:
🎙 Un <b>audio</b> contando el trabajo realizado
⌨️ Un <b>mensaje de texto</b> con el detalle
Incluye: equipo, falla, actividades y repuestos usados.

Después te muestro una <b>vista previa</b> (todavía sin guardar) y tú decides:
✅ <b>Confirmar</b> → se registra y supervisión lo ve en el panel
✏️ <b>Corregir</b> → me dices qué cambiar y actualizo el borrador

También puedes escribir «confirmar» o «corregir» en lugar de pulsar los botones.`;
}
return [{ json: { tg_method: 'sendMessage', tg: { chat_id: c.chat_id, parse_mode: 'HTML', text } } }];

const ctx = $('Verificar autorizacion').first().json;
const j = $input.first().json;
const texto = String(ctx.kind === 'voice' ? (j.text || '') : (ctx.text || '')).trim();
// texto normalizado para detectar saludos / palabras clave
const n = texto.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9\s]/g, ' ').replace(/\s+/g, ' ').trim();
const words = n ? n.split(' ').length : 0;
let intent = 'reporte';
if (!texto) intent = 'vacio';
else if (/^(si |ok )?(confirmar|confirmo|confirmado|guardar|guardalo)( reporte)?$/.test(n)) intent = 'confirmar';
else if (/^(quiero |voy a )?(corregir|correccion|editar|modificar)(lo| reporte)?$/.test(n)) intent = 'corregir';
else if (words <= 4 && /^(hola|holi|ola|hey|buenas|buenos dias|buen dia|buenas tardes|buenas noches|que tal|saludos)/.test(n)) intent = 'saludo';
return [{ json: { ...ctx, texto, intent } }];

const ctx = $('Armar prompt').first().json;
const resp = $input.first().json;
let d = {};
try {
  let content = resp.choices[0].message.content;
  if (typeof content === 'string') {
    content = content.replace(/^```json\s*/i, '').replace(/```\s*$/i, '').trim();
    d = JSON.parse(content);
  } else if (typeof content === 'object') {
    d = content;
  }
} catch (e) {
  d = {};
}

const s = (v) => (v === null || v === undefined || String(v).trim() === '') ? null : String(v).trim();
const num = (v) => (v === null || v === undefined || v === '') ? null : (Number.isFinite(Number(v)) ? Number(v) : null);
const arr = (v) => Array.isArray(v) ? v.map((x) => String(x).trim()).filter(Boolean) : [];
const pick = (v, list) => {
  const x = String(v || '').toLowerCase().trim();
  return list.includes(x) ? x : null;
};

// Herramientas sanitizadas
const herramientas = (Array.isArray(d.herramientas) ? d.herramientas : [])
  .map((h) => {
    if (typeof h === 'string') {
      return { nombre: s(h), modelo: null, procedencia: 'GMO' };
    }
    const nom = s(h && h.nombre);
    if (!nom) return null;
    const procRaw = String((h && h.procedencia) || '').toUpperCase();
    const procedencia = procRaw === 'EXT' ? 'EXT' : 'GMO';
    return {
      nombre: nom,
      modelo: s(h && h.modelo),
      procedencia
    };
  })
  .filter(Boolean);

// Materiales Consumibles sanitizados
const materiales_consumibles = (Array.isArray(d.materiales_consumibles) ? d.materiales_consumibles : [])
  .map((m) => {
    if (typeof m === 'string') {
      return { nombre: s(m), cantidad: null, unidad: null, codigo: null, procedencia: 'GMO' };
    }
    const nom = s(m && m.nombre);
    if (!nom) return null;
    const procRaw = String((m && m.procedencia) || '').toUpperCase();
    const procedencia = procRaw === 'EXT' ? 'EXT' : 'GMO';
    return {
      nombre: nom,
      cantidad: num(m && m.cantidad),
      unidad: s(m && m.unidad),
      codigo: s(m && m.codigo),
      procedencia
    };
  })
  .filter(Boolean);

// Repuestos capitalizables sanitizados
const repuestos = (Array.isArray(d.repuestos) ? d.repuestos : [])
  .map((r) => {
    if (typeof r === 'string') {
      return { nombre: s(r), cantidad: null, codigo: null };
    }
    const nom = s(r && r.nombre);
    if (!nom) return null;
    return {
      nombre: nom,
      cantidad: num(r && r.cantidad),
      codigo: s(r && r.codigo)
    };
  })
  .filter(Boolean);

// Cálculo o validación de duración si hay horas de inicio y fin
let duracionCalc = num(d.duracion_minutos);
const horaInicio = s(d.hora_inicio);
const horaFin = s(d.hora_fin);
const fechaInicio = /^\d{4}-\d{2}-\d{2}$/.test(String(d.fecha_inicio || '')) ? d.fecha_inicio : null;
const fechaFin = /^\d{4}-\d{2}-\d{2}$/.test(String(d.fecha_fin || '')) ? d.fecha_fin : (fechaInicio || null);

if (duracionCalc === null && horaInicio && horaFin) {
  const fi = fechaInicio || '2000-01-01';
  const ff = fechaFin || fi;
  const t1 = new Date(`${fi}T${horaInicio.length === 5 ? horaInicio + ':00' : horaInicio}`).getTime();
  const t2 = new Date(`${ff}T${horaFin.length === 5 ? horaFin + ':00' : horaFin}`).getTime();
  if (!isNaN(t1) && !isNaN(t2) && t2 > t1) {
    duracionCalc = Math.round((t2 - t1) / 60000);
  }
}

const campos = {
  // Datos Generales
  numero_ot: s(d.numero_ot),
  unidad: s(d.unidad),
  ow_os: s(d.ow_os),
  puesto_trabajo: s(d.puesto_trabajo),
  titulo_trabajo: s(d.titulo_trabajo),
  equipo: s(d.equipo),
  codigo_equipo: s(d.codigo_equipo),
  area: s(d.area),
  tipo_mantenimiento: pick(d.tipo_mantenimiento, ['preventivo', 'correctivo', 'predictivo', 'inspeccion', 'otro']),
  tipo_notificacion: pick(d.tipo_notificacion, ['parcial', 'final']),
  prioridad: pick(d.prioridad, ['baja', 'media', 'alta', 'critica']),

  // Tiempos y Fechas
  fecha_inicio: fechaInicio,
  hora_inicio: horaInicio,
  fecha_fin: fechaFin,
  hora_fin: horaFin,
  fecha_intervencion: fechaInicio,
  duracion_minutos: duracionCalc === null ? null : Math.max(0, Math.round(duracionCalc)),
  total_horas_hombre: num(d.total_horas_hombre),

  // Diagnóstico y Trabajo
  falla: s(d.falla),
  causa_probable: s(d.causa_probable),
  actividades: arr(d.actividades),

  // Herramientas, Materiales y Repuestos
  herramientas,
  materiales_consumibles,
  repuestos,

  // Observaciones y Aviso SAP
  observaciones: s(d.observaciones),
  requiere_aviso: Boolean(d.requiere_aviso),

  // Personal y Supervisión
  supervisor_operaciones: s(d.supervisor_operaciones),
  responsable_ejecucion: s(d.responsable_ejecucion),
  responsable_trabajo_nombre: s(d.responsable_trabajo_nombre),
  responsable_trabajo_telefono: s(d.responsable_trabajo_telefono),

  // Confianza y Ambigüedad
  confianza: num(d.confianza) === null ? null : Math.min(1, Math.max(0, Number(d.confianza))),
  necesita_confirmacion: Boolean(d.necesita_confirmacion),
  pregunta_aclaracion: s(d.pregunta_aclaracion)
};

const faltantes = [];
if (!campos.equipo) faltantes.push('equipo');
if (!campos.falla) faltantes.push('falla / síntoma');
if (!campos.actividades.length) faltantes.push('actividades ejecutadas');

const ms = Date.now() - (ctx.t0 || Date.now());
let mode, db_row;

if (ctx.orig_id) {
  mode = 'update';
  db_row = {
    ...campos,
    campos_faltantes: faltantes,
    raw_ia: d,
    texto_correccion: ctx.texto,
    estado: 'corregido',
    correcciones: (ctx.orig_correcciones || 0) + 1,
    tiempo_procesamiento_ms: ms
  };
} else {
  mode = 'new';
  db_row = {
    telegram_chat_id: ctx.chat_id,
    telegram_message_id: ctx.message_id,
    tecnico_nombre: ctx.tecnico_registrado || ctx.from_name,
    tecnico_username: ctx.username || null,
    origen: ctx.kind === 'voice' ? 'audio' : 'texto',
    audio_duracion_seg: ctx.kind === 'voice' ? ctx.duration : null,
    texto_original: ctx.texto,
    ...campos,
    campos_faltantes: faltantes,
    raw_ia: d,
    estado: 'borrador',
    tiempo_procesamiento_ms: ms
  };
}

return [{ json: { ...ctx, mode, db_row } }];

const esc = (t) => String(t === null || t === undefined ? '' : t)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

const r = $input.first().json;
const p = $('Procesar respuesta IA').first().json;
const raw = p.db_row || {};
const L = [];

L.push(`📋 <b>VISTA PREVIA DEL REPORTE</b>${p.mode === 'update' ? ' · <i>Actualizado</i>' : ''}`);
L.push('<i>Estado: Borrador activo (aún no registrado en el panel)</i>', '');

// Identificación
if (r.numero_ot) {
  L.push(`🏷 <b>Orden de Trabajo (OT):</b> <code>${esc(r.numero_ot)}</code>`);
}
const metaId = [];
if (r.unidad) metaId.push(`Unidad: <b>${esc(r.unidad)}</b>`);
if (r.puesto_trabajo) metaId.push(`Puesto: <b>${esc(r.puesto_trabajo)}</b>`);
if (r.ow_os) metaId.push(`OW/OS: <b>${esc(r.ow_os)}</b>`);
if (metaId.length) L.push(`🏭 ${metaId.join(' · ')}`);

if (r.titulo_trabajo) {
  L.push(`📌 <b>Título:</b> ${esc(r.titulo_trabajo)}`);
}

L.push(`🔧 <b>Equipo:</b> ${esc(r.equipo || '—')}${r.codigo_equipo ? ' (Tag: <code>' + esc(r.codigo_equipo) + '</code>)' : ''}`);
if (r.area) L.push(`📍 <b>Área:</b> ${esc(r.area)}`);

const regimen = [];
if (r.tipo_notificacion) regimen.push(`Notif. <b>${esc(r.tipo_notificacion).toUpperCase()}</b>`);
if (r.tipo_mantenimiento) regimen.push(`Tipo: <b>${esc(r.tipo_mantenimiento)}</b>`);
if (r.prioridad) regimen.push(`Prioridad: <b>${esc(r.prioridad)}</b>`);
if (regimen.length) L.push(`⚙️ ${regimen.join(' · ')}`);

// Horarios y Duración
const horario = [];
if (r.hora_inicio || r.hora_fin) {
  horario.push(`⏰ <b>Horario:</b> ${esc(r.hora_inicio || '—')} a ${esc(r.hora_fin || '—')}`);
}
if (r.duracion_minutos !== null && r.duracion_minutos !== undefined) {
  horario.push(`⏱ ${esc(r.duracion_minutos)} min`);
}
if (r.total_horas_hombre !== null && r.total_horas_hombre !== undefined) {
  horario.push(`👥 <b>${esc(r.total_horas_hombre)} H-H</b>`);
}
if (horario.length) L.push(horario.join(' · '));

// Diagnóstico
L.push(`⚠️ <b>Falla / Anomalía:</b> ${esc(r.falla || '—')}`);
if (r.causa_probable) L.push(`🔍 <b>Causa probable:</b> ${esc(r.causa_probable)}`);

// Actividades y Mediciones
L.push('🛠 <b>Trabajo Ejecutado y Mediciones:</b>');
const acts = r.actividades || [];
if (acts.length) {
  acts.forEach((a, i) => L.push(`  ${i + 1}. ${esc(a)}`));
} else {
  L.push('  —');
}

// Herramientas
const tools = r.herramientas || [];
if (tools.length) {
  L.push('🧰 <b>Herramientas Usadas:</b>');
  tools.forEach((h) => {
    L.push(`  • ${esc(h.nombre)}${h.modelo ? ` [${esc(h.modelo)}]` : ''} <i>(${esc(h.procedencia || 'GMO')})</i>`);
  });
}

// Materiales Consumibles
const mats = r.materiales_consumibles || [];
if (mats.length) {
  L.push('📦 <b>Materiales Consumibles:</b>');
  mats.forEach((m) => {
    const cantStr = m.cantidad !== null && m.cantidad !== undefined ? ` x${esc(m.cantidad)} ${esc(m.unidad || 'un.')}` : ' (cant. no esp.)';
    L.push(`  • ${esc(m.nombre)}${cantStr}${m.codigo ? ` [Cód: ${esc(m.codigo)}]` : ''} <i>(${esc(m.procedencia || 'GMO')})</i>`);
  });
}

// Repuestos
const reps = r.repuestos || [];
if (reps.length) {
  L.push('🔩 <b>Repuestos Capitalizables:</b>');
  reps.forEach((x) => {
    L.push(`  • ${esc(x.nombre)}${x.cantidad ? ` x${esc(x.cantidad)}` : ''}${x.codigo ? ` (${esc(x.codigo)})` : ''}`);
  });
}

// Observaciones y Aviso SAP
if (r.observaciones) {
  L.push(`📝 <b>Observaciones:</b> ${esc(r.observaciones)}`);
}
if (r.requiere_aviso) {
  L.push(`🔔 <b>Aviso SAP / GMAO:</b> Requiere generar aviso por observaciones`);
}

// Supervisión
const superv = [];
if (r.supervisor_operaciones) superv.push(`Sup. Op: ${esc(r.supervisor_operaciones)}`);
if (r.responsable_ejecucion) superv.push(`Resp. Ejec: ${esc(r.responsable_ejecucion)}`);
if (r.responsable_trabajo_nombre) superv.push(`Resp. Trab: ${esc(r.responsable_trabajo_nombre)}`);
if (superv.length) L.push(`👷 ${superv.join(' · ')}`);

// Alertas de Ambigüedad o Datos Faltantes
if (raw.necesita_confirmacion && raw.pregunta_aclaracion) {
  L.push('', `❓ <b>Confirmación requerida:</b> ${esc(raw.pregunta_aclaracion)}`);
}

const falt = r.campos_faltantes || [];
if (falt.length) {
  L.push('', `❗ <b>Faltan datos:</b> ${esc(falt.join(', '))}. Pulsa ✏️ Corregir para completarlos.`);
}

L.push('', '¿Todo conforme? ✅ <b>Confirmar</b> para publicar al panel o ✏️ <b>Corregir</b> para cambiar datos.');

return [{
  json: {
    tg_method: 'sendMessage',
    tg: {
      chat_id: p.chat_id,
      parse_mode: 'HTML',
      text: L.join('\n'),
      reply_markup: {
        inline_keyboard: [
          [
            { text: '✅ Confirmar', callback_data: 'ok:' + r.id },
            { text: '✏️ Corregir', callback_data: 'ed:' + r.id }
          ]
        ]
      }
    }
  }
}];

const c = $input.first().json;
const m = String(c.data || '').match(/^(ok|ed):([0-9a-fA-F-]{36})$/);
return [{ json: { ...c, action: m ? m[1] : 'otro', report_id: m ? m[2] : null } }];

const esc = (t) => String(t === null || t === undefined ? '' : t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const c = $('Unificar confirmacion').first().json;
const r = $input.first().json || {};
const ok = !!r.id;
const out = [];
if (c.callback_id) out.push({ json: { tg_method: 'answerCallbackQuery', tg: { callback_query_id: c.callback_id, text: ok ? 'Reporte confirmado ✅' : 'Este reporte ya fue procesado' } } });
if (c.callback_id && c.message_id) out.push({ json: { tg_method: 'editMessageReplyMarkup', tg: { chat_id: c.chat_id, message_id: c.message_id, reply_markup: { inline_keyboard: [] } } } });
const eq = r.equipo ? ` de <b>${esc(r.equipo)}</b>` : '';
const text = ok
  ? `✅ <b>Reporte confirmado</b>${eq}\nYa quedó registrado y supervisión puede verlo en el panel.`
  : 'ℹ️ Ese reporte ya fue confirmado o ya no está disponible. Envíame un nuevo audio o texto para crear otro.';
out.push({ json: { tg_method: 'sendMessage', tg: { chat_id: c.chat_id, parse_mode: 'HTML', text } } });
return out;

const c = $('Unificar correccion').first().json;
const r = $input.first().json || {};
const out = [];
if (c.callback_id) out.push({ json: { tg_method: 'answerCallbackQuery', tg: { callback_query_id: c.callback_id } } });
const text = r.id
  ? `✏️ <b>Modo corrección</b>\nEnvíame por <b>texto o audio</b> solo lo que quieres cambiar o agregar. Yo actualizo el borrador y te muestro una nueva vista previa.\n\n<b>Ejemplos:</b>\n• «La falla fue sobrecalentamiento del motor»\n• «El equipo es la bomba P-101A, no la P-101B»\n• «Agrega 2 fusibles de 10 A como repuesto»\n• «La duración fue de 90 minutos»`
  : 'ℹ️ Ese reporte ya fue confirmado o ya no está disponible para corregir. Envíame un nuevo audio o texto para crear otro.';
out.push({ json: { tg_method: 'sendMessage', tg: { chat_id: c.chat_id, parse_mode: 'HTML', text } } });
return out;

const esc = (t) => String(t === null || t === undefined ? '' : t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const c = $input.first().json;
const eq = c.equipo ? ` de <b>${esc(c.equipo)}</b>` : '';
let text;
if (c.estado === 'revisado') {
  text = `✅ Tu reporte${eq} fue <b>validado</b> por supervisión.`;
  if (c.comentario) text += `\nComentario: ${esc(c.comentario)}`;
} else {
  text = `❌ Tu reporte${eq} fue <b>rechazado</b> por supervisión.`;
  if (c.comentario) text += `\nMotivo: ${esc(c.comentario)}`;
}
return [{ json: { tg_method: 'sendMessage', tg: { chat_id: c.chat_id, parse_mode: 'HTML', text } } }];

let ctx = {};
try { ctx = $('Normalizar').first().json; } catch (e) {}
if (!ctx.chat_id) return [];
return [{ json: { tg_method: 'sendMessage', tg: { chat_id: ctx.chat_id, parse_mode: 'HTML', text: '⚠️ No pude procesar tu mensaje. Inténtalo de nuevo o envíalo como texto. Si persiste, avisa a tu supervisor.' } } }];

const item = $input.first();
item.binary.data.fileName = 'audio.ogg';
item.binary.data.mimeType = 'audio/ogg';
return [{ json: item.json, binary: item.binary }];

const ctx = $('Preparar texto').first().json;
const drafts = $input.all().map((i) => i.json).filter((x) => x && x.id);
drafts.sort((a, b) => String(b.created_at || '').localeCompare(String(a.created_at || '')));

const editing = drafts.find((d) => d.estado === 'editando') || null;
const singleDraft = drafts.length === 1 ? drafts[0] : null;
const draft = editing || singleDraft || drafts[0] || null;

let route = 'reporte';
if (ctx.intent === 'vacio') {
  route = 'sin_texto';
} else if (ctx.intent === 'saludo') {
  route = 'saludo';
} else if (ctx.intent === 'confirmar') {
  route = draft ? 'confirmar' : 'sin_borrador';
} else if (ctx.intent === 'corregir') {
  if (drafts.length > 1 && !editing) {
    route = 'aclarar_borrador';
  } else {
    route = draft ? 'corregir' : 'sin_borrador';
  }
}

return [{
  json: {
    ...ctx,
    route,
    report_id: draft ? draft.id : null,
    draft: editing || (ctx.intent === 'corregir' ? draft : null)
  }
}];

const esc = (t) => String(t === null || t === undefined ? '' : t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const c = $input.first().json;
const nombre = esc(c.tecnico_registrado || c.first_name || 'técnico');
const text = `👋 Hola, <b>${nombre}</b>. Soy <b>MaintAI</b>, tu asistente de reportes de mantenimiento.

